; $026A60-$026A80 LONG JUMP LOCATION
Hobo_Draw:
{
    PHB : PHK : PLB
    
    LDA.b #$04 : STA.b $06
                 STZ.b $07
    
    LDA.w $0DC0, X : ASL #5
    
    ADC.b #.OAM_groups                 : STA.b $08
    LDA.b #.OAM_groups>>8 : ADC.b #$00 : STA.b $09
    
    JSL.l Sprite_DrawMultiple_player_deferred
    
    PLB
    
    RTL
}

