; $026A81-$026A9C LONG JUMP LOCATION
Landmine_CheckDetonationFromHammer:
{
    LDA.w $0301 : AND.b #$0A : BEQ .player_not_using_hammer
        ; Check if the player is currently in a "hidden off-screen" state.
        ; Usually occurs when exiting a dungeon.
        LDA.b $44 : CMP.b #$80 : BEQ .cant_check
            JSL.l Player_SetupActionHitBoxLong
            JSL.l Sprite_SetupHitBoxLong
            JSL.l Utility_CheckIfHitBoxesOverlapLong
            
            RTL
        
        .cant_check
    .player_not_using_hammer
    
    CLC
    
    RTL
}

; ==============================================================================

; $026A9D-$026B32 LONG JUMP LOCATION
EasterEgg_BageCode:
{
    ; Code that utilizes the player's name (hidden, secret, awesome!!).
    
    LDA.b $F2 : AND.b #$10 : BNE .r_button_held
        JMP.w .fail
    
    .r_button_held
    
    REP #$20
    
    ; These are to check if your name is 'BAGE' (US rom) or ... 'iayuo'
    ; (JP rom) neither one makes much sense to me. BAGE' could be 'bad game'
    ; as has been suggested.
    LDA.l $7003D9 : CMP.w #$0001 : BNE .fail
    LDA.l $7003DB : CMP.w #$0000 : BNE .fail
    LDA.l $7003DD : CMP.w #$0006 : BNE .fail
    LDA.l $7003DF : CMP.w #$0004 : BNE .fail
        SEP #$20
        
        ; Grant 1/2 magic consumption.
        LDA.b #$01 : STA.l $7EF37B
        
        LDA.b $F6
        JSL.l BAGE_HandleSword
        
        LDA.l $7EF359 : CMP.b #$04 : BNE .not_golden_sword
            LDA.b #$03 : STA.l $7EF35A
            DEC      : STA.l $7EF35B
        
        .not_golden_sword
        
        LDA.b $F4 : BPL .b_button_not_pressed
            ; Turn on walk through walls code.
            LDA.w $037F : EOR.b #$01 : STA.w $037F
        
        .b_button_not_pressed
        
        BIT.b $F4 : BVS .y_button_not_pressed
            ; Refill all hearts, magic, bombs, and arrows.
            LDA.b #$FF
            STA.l $7EF372 : STA.l $7EF373
            STA.l $7EF375 : STA.l $7EF376
            
            ; Add 255 rupees to the player's stash.
            CLC : ADC.l $7EF360 : STA.l $7EF360
            LDA.l $7EF361 : ADC.b #$00 : STA.l $7EF361
            
            ; Give the player 9 keys.
            LDA.b #$09 : STA.l $7EF36F
        
        .y_button_not_pressed
        
        RTL
    
    .fail
    
    SEP #$20
    
    ; Joypad 2 R button is not being held.
    LDA.b $F3 : AND.b #$10 : BEQ BAGE_HandleSword_return
        ; Joypad 2 A button was not pressed this frame.
        LDA.b $F7

    ; Bleeds into the next function.
}
        
; $026B33-$026B62 LONG JUMP LOCATION
BAGE_HandleSword:
{
    BPL .return
        LDA.l $7EF359 : INC : CMP.b #$05 : BCC .valid_sword
            LDA.b #$01
            
        .valid_sword
            
        STA.l $7EF359
            
        LDA.l $7EF35B : INC : CMP.b #$03 : BNE .valid_armor
            LDA.b #$00
            
        .valid_armor
            
        STA.l $7EF35B
            
        LDA.l $7EF35A : INC : CMP.b #$04 : BNE .valid_shield
            LDA.b #$01
            
        .valid_shield
            
        STA.l $7EF35A
    
    .return
    
    RTL
}

