; $026B63-$026BA9 LONG JUMP LOCATION
Bomb_ProjectSpeedTowardsPlayer:
{
    LDX.b #$00
    
    LDA.w $0D10, X : PHA
    LDA.w $0D30, X : PHA
    
    LDA.w $0D00, X : PHA
    LDA.w $0D20, X : PHA
    
    LDA.w $0F70, X : PHA
    
    LDA.b $00 : STA.w $0D10, X
    LDA.b $01 : STA.w $0D30, X
    
    LDA.b $02 : STA.w $0D00, X
    LDA.b $03 : STA.w $0D20, X
    
    STZ.w $0F70, X
    
    TYA
    
    JSL.l Sprite_ProjectSpeedTowardsPlayerLong
    
    PLA : STA.w $0F70, X
    
    PLA : STA.w $0D20, X
    PLA : STA.w $0D00, X
    
    PLA : STA.w $0D30, X
    PLA : STA.w $0D10, X
    
    RTL
}

; ==============================================================================

; The name of this routine has more to do with its only caller than with what
; it actually does. Anybody could call this and it would do the same thing
; regardless. However, the only caller of this subroutine replaced the player's
; coordinates with an ancillary object's coordinates (specifically, only bombs
; call this routine's caller).
; $026BAA-$026BB2 LONG JUMP LOCATION
Bomb_ProjectReflexiveSpeedOntoSpriteLong:
{
    PHB : PHK : PLB
    
    JSL.l Sprite_ProjectSpeedTowardsPlayerLong
    
    PLB
    
    RTL
}

