; $026BB3-$026BE4 DATA
Pool_Sprite_DrawLargeWaterTurbulence:
{
    .OAM_groups
    dw -10, 14 : db $C0, $00, $00, $02
    dw  -5, 16 : db $C0, $40, $00, $02
    dw  -2, 18 : db $C0, $00, $00, $02
    dw   2, 18 : db $C0, $40, $00, $02
    dw   5, 16 : db $C0, $00, $00, $02
    dw  10, 14 : db $C0, $40, $00, $02
    
    .properties
    db $04, $44
}

; $026BE5-$026C1B LONG JUMP LOCATION
Sprite_DrawLargeWaterTurbulence:
{
    PHB : PHK : PLB
    
    LDA.w $0F50, X : PHA
    
    LDA.w $0E80, X : LSR : AND.b #$01 : TAY
    LDA.w .properties, Y : STA.w $0F50, X
    
    ; BUG: Why is this load not used?
    LDA.b #$18
    
    LDA.w $0B89, X : AND.b #$F0 : STA.w $0B89, X
    
    JSL.l OAM_AllocateFromRegionC
    
    REP #$20
    
    LDA.w #(.OAM_groups) : STA.b $08
    
    SEP #$20
    
    LDA.b #$06
    JSL.l Sprite_DrawMultiple
    
    PLA : STA.w $0F50, X
    
    PLB
    
    RTL
}
    
